class Solution {
    private int[][] first,second;
    private boolean dfs(int row,int col){
        if(row<0||row==second.length||col<0||col==second[0].length||second[row][col]==0)return true;
        second[row][col]=0;
        boolean valid=first[row][col]==1;
        valid=dfs(row+1,col)&valid;
        valid=dfs(row-1,col)&valid;
        valid=dfs(row,col+1)&valid;
        valid=dfs(row,col-1)&valid;
        return valid;
    }
    public int countSubIslands(int[][] grid1,int[][] grid2){
        first=grid1;
        second=grid2;
        int answer=0;
        for(int row=0;row<grid2.length;row++)for(int col=0;col<grid2[0].length;col++)if(grid2[row][col]==1&&dfs(row,col))answer++;
        return answer;
    }
}

